entries[225701] = { ["name"] = "Champion: Moderdarm", ["text"] = "Sofort\nDie Monstrosität ist eine von Kel'Thuzads pragmatischsten Kreaturen. Was könnte nützlicher sein als ein gewaltiges, missgestaltetes Ungetüm mit absoluter Loyalität und einem unstillbaren Hunger darauf, seine Gegner zu verschlingen? Was Monstrositäten angeht, ist Moderdarm ein mustergültiges Exemplar." }
