entries[226731] = { ["name"] = "Arkanbeschuss", ["text"] = "40 Meter Reichweite\nSofort 2 sek. Abklingzeit\nFügt einem Gegner Arkanschaden zu." }
entries[226737] = { ["name"] = "Ettinwut", ["text"] = "Wirken in 2 sek.\nBrüllt mit großer Wildheit und erhöht den verursachten körperlichen Schaden für 10 Sek. um 50%." }
